// Vader Mode V2.4 embedded media bootstrap.
// Media is reconstructed as Blob URLs at runtime so the app does not depend on relative file paths.
(() => {
  'use strict';
  const EMBEDDED = {"vader-army.webp":{"mime":"image/webp","b64":""},"vader-breathing-original.mp3":{"mime":"audio/mpeg","b64":""},"vader-closeup.webp":{"mime":"image/webp","b64":""},"vader-clouds.webp":{"mime":"image/webp","b64":""},"vader-command.webp":{"mime":"image/webp","b64":""},"vader-corridor.webp":{"mime":"image/webp","b64":""},"vader-mask-art.webp":{"mime":"image/webp","b64":""},"vader-portrait-red.webp":{"mime":"image/webp","b64":""},"vader-red-face.webp":{"mime":"image/webp","b64":""},"vader-saber-dark.webp":{"mime":"image/webp","b64":""},"vader-silhouette.webp":{"mime":"image/webp","b64":""},"vader-smoke.webp":{"mime":"image/webp","b64":""}};
  const cache = new Map();
  const bytesCache = new Map();
  function keyOf(name){ return String(name||'').split('/').pop(); }
  function bytes(name){
    const key=keyOf(name);
    if(bytesCache.has(key)) return bytesCache.get(key);
    const item=EMBEDDED[key]; if(!item) return null;
    const raw=atob(item.b64);
    const arr=new Uint8Array(raw.length);
    for(let i=0;i<raw.length;i++) arr[i]=raw.charCodeAt(i);
    bytesCache.set(key,arr);
    return arr;
  }
  function url(name){
    const key=keyOf(name);
    if(cache.has(key)) return cache.get(key);
    const item=EMBEDDED[key];
    if(!item) return name;
    try {
      const arr=bytes(key);
      const u=URL.createObjectURL(new Blob([arr],{type:item.mime}));
      cache.set(key,u); return u;
    } catch(e) {
      const u=`data:${item.mime};base64,${item.b64}`;
      cache.set(key,u); return u;
    }
  }
  function mime(name){ const item=EMBEDDED[keyOf(name)]; return item?.mime || ''; }
  function has(name){ return !!EMBEDDED[keyOf(name)]; }
  function names(){ return Object.keys(EMBEDDED); }
  window.VaderMedia={url,bytes,mime,has,names};
})();
